import clsx from 'clsx';

interface PlatformIconProps {
  platform: string;
  size?: number;
  className?: string;
}

export function PlatformIcon({ platform, size = 18, className }: PlatformIconProps) {
  const icon = PLATFORM_SVG_ICONS[platform];
  if (!icon) {
    return <span className={clsx('inline-flex items-center justify-center', className)} style={{ width: size, height: size }}>🔗</span>;
  }

  return (
    <svg
      viewBox={icon.viewBox}
      width={size}
      height={size}
      className={clsx('inline-block shrink-0', className)}
      aria-label={icon.name}
    >
      {icon.paths.map((p, i) => (
        <path key={i} d={p.d} fill={p.fill} stroke={p.stroke} transform={p.transform} />
      ))}
    </svg>
  );
}

